import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as e,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"Trae 学习地图","description":"TraeCode 是字节跳动面向开发者的 AI 编程 IDE（IDE 模式 + SOLO 模式）。同厂的 TraeWork、豆包、扣子、火山方舟不是这个产品。本目录只教你从官方下载装上 TraeCode，打开第一个项目。","frontmatter":{"title":"Trae 学习地图","description":"TraeCode 是字节跳动面向开发者的 AI 编程 IDE（IDE 模式 + SOLO 模式）。同厂的 TraeWork、豆包、扣子、火山方舟不是这个产品。本目录只教你从官方下载装上 TraeCode，打开第一个项目。","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"zh/products/trae/index.md","filePath":"zh/products/trae/index.md","lastUpdated":1787107158000}'),s={name:"zh/products/trae/index.md"};function o(d,t,l,i,p,h){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="trae-学习地图" tabindex="-1">Trae 学习地图 <a class="header-anchor" href="#trae-学习地图" aria-label="Permalink to &quot;Trae 学习地图&quot;">​</a></h1><blockquote><p><strong>TraeCode</strong> 是 TRAE 品牌下的 AI 编程 IDE。官方原文（<a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a>）：深度融合 AI 的开发工具，覆盖编码、项目理解、调试运行和变更管理。你可以像传统 IDE 一样掌控每一步，也可以把复杂任务交给智能体。</p><p>营销首页（<a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a>）把它和 <strong>TraeWork</strong> 并排：<strong>TraeCode: Your 10x AI Coding Engineer</strong>；<strong>TraeWork: Your Professional AI Work Assistant</strong>。本目录只展开 TraeCode。</p></blockquote><h2 id="写给谁-先决条件" tabindex="-1">写给谁 / 先决条件 <a class="header-anchor" href="#写给谁-先决条件" aria-label="Permalink to &quot;写给谁 / 先决条件&quot;">​</a></h2><ul><li><strong>写给谁</strong>：已经会用桌面 IDE 的前端工程师，想对位 Cursor 的字节跳动 AI IDE。</li><li><strong>先决条件</strong>：官方 <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">快速开始</a> / <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">中国站快速开始</a> 列出的操作系统（见下表）；一个 TRAE 账号。</li><li><strong>非目标</strong>：不教 TraeWork 办公工作台；不教豆包 / 扣子 / 火山方舟；不教模型内部机制（去 Learn LLM）；不编 TraeCode CLI 命令（企业页写 <strong>coming soon</strong>）。</li></ul><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>字节跳动 TRAE 官方一级入口必须先对账。本目录<strong>只展开 TraeCode</strong>。其余各占一行。下表「官方名称」抄自 2026-08-19 打开的官方页，不是本站自造名。</p><table tabindex="0"><thead><tr><th>官方名称</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>TraeCode</strong>（AI 编程 IDE）</td><td><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a> · <a href="https://www.trae.ai/download" target="_blank" rel="noreferrer">Download Center</a></td><td>本目录主路径</td></tr><tr><td><strong>TraeCode 文档</strong></td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai · What is TraeCode?</a> · <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">快速开始</a></td><td>本页 · <a href="./trae.html">教程</a></td></tr><tr><td><strong>TraeWork</strong></td><td><a href="https://www.trae.ai/work" target="_blank" rel="noreferrer">www.trae.ai/work</a> · <a href="https://docs.trae.ai/solo/what-is-trae-solo" target="_blank" rel="noreferrer">What is TRAE Work?</a></td><td>地图一行：办公工作台，不拆教程</td></tr><tr><td><strong>TraeCode Plugin</strong></td><td><a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">企业页</a>（原文：VS Code、JetBrains and other mainstream editors）</td><td>地图一行：嵌进已有编辑器，不是本 IDE 教程</td></tr><tr><td><strong>TRAE Enterprise</strong></td><td><a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">www.trae.ai/enterprise</a></td><td>地图一行：团队采购</td></tr><tr><td><strong>TraeCode CLI</strong></td><td>企业页原文 <strong>coming soon</strong></td><td>地图一行：未上线，禁止编命令</td></tr><tr><td><strong>TRAE Editor for Unity</strong></td><td><a href="https://docs.trae.cn/ide_trae-editor-for-unity-tutorial.md" target="_blank" rel="noreferrer">中国站教程</a></td><td>地图一行：Unity 插件</td></tr><tr><td><strong>中国站 TraeCode / TraeWork</strong></td><td><a href="https://www.trae.cn/" target="_blank" rel="noreferrer">www.trae.cn</a> · 快速开始链 <a href="https://www.trae.com.cn" target="_blank" rel="noreferrer">www.trae.com.cn</a> · <a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">docs.trae.cn</a></td><td><a href="./trae.html#1-选表面中国站-vs-国际站">教程 · 分表面安装</a></td></tr><tr><td><strong>火山引擎 TRAE</strong></td><td><a href="https://www.volcengine.com/product/trae" target="_blank" rel="noreferrer">volcengine.com/product/trae</a></td><td>地图一行：CN 云产品位</td></tr><tr><td><strong>豆包</strong></td><td>另 issue #79</td><td>一行 → 将有的 <a href="/zh/products/doubao/">豆包家族</a></td></tr><tr><td><strong>扣子 Coze</strong></td><td>另 issue #81</td><td>一行 → 将有的 <a href="/zh/products/coze/">扣子家族</a></td></tr><tr><td><strong>火山方舟 Ark</strong></td><td>另 issue #82</td><td>一行 → <a href="/zh/products/volcengine-ark/">火山方舟</a></td></tr></tbody></table><p>来源：<a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a>、<a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai 顶栏</a>、<a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">企业页</a>、<a href="https://www.trae.cn/" target="_blank" rel="noreferrer">www.trae.cn</a>、<a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer">docs.trae.cn/llms.txt</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TRAE（品牌）</span></span>
<span class="line"><span>├── TraeCode — 桌面 AI 编程 IDE（本目录）</span></span>
<span class="line"><span>│   ├── IDE 模式（编辑器 / 终端 / 调试 / 插件 / Git）</span></span>
<span class="line"><span>│   ├── SOLO 模式（AI 主导：规划 → 生成 → 测试 → 预览）</span></span>
<span class="line"><span>│   ├── CUE / Agent / Skills / Rules / MCP</span></span>
<span class="line"><span>│   ├── TraeCode Plugin（嵌进 VS Code / JetBrains，地图一行）</span></span>
<span class="line"><span>│   └── TraeCode CLI（官方 coming soon）</span></span>
<span class="line"><span>├── TraeWork — 独立办公工作台（Web / Desktop / Mobile）</span></span>
<span class="line"><span>│   └── Work / Code（营销页另写 Design）</span></span>
<span class="line"><span>├── TRAE Enterprise — 团队</span></span>
<span class="line"><span>└── 同厂其它 AI（本目录不展开）</span></span>
<span class="line"><span>    ├── 豆包 #79</span></span>
<span class="line"><span>    ├── 扣子 #81</span></span>
<span class="line"><span>    └── 火山方舟 #82</span></span></code></pre></div><p><strong>容易撞名：</strong></p><ul><li><strong>TraeCode ≠ TraeWork。</strong> 前者是编程 IDE；后者是办公工作台。官方：<a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">TraeWork builds upon TraeCode&#39;s SOLO mode</a>。</li><li><strong>TraeCode 里的 SOLO 模式 ≠ TraeWork。</strong> SOLO 是 IDE 左上角的模式开关；TraeWork 是独立客户端（Web / Desktop / Mobile）。</li><li><strong>旧名 TRAE IDE / TRAE SOLO 独立端</strong> 已收进 TraeCode / TraeWork，不要再当第三个产品装。</li><li><strong>CUE ≠ Cursor。</strong> CUE 是 TraeCode 的补全 / 多行修改 / 修改点预测。</li><li><strong>TraeCode Plugin ≠ TraeCode 扩展市场。</strong> Plugin 把能力嵌进 VS Code / JetBrains；扩展市场是 IDE 里装语言/调试插件。</li><li><strong><code>trae.ai</code> ≠ <code>trae.cn</code> / <code>trae.com.cn</code>。</strong> 国际站顶栏有「前往中国站」。两套登录、额度、设备上限。不要混用账号。</li></ul><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在本机仓库里写代码 / 改代码 / 调试 / 补全</span></span>
<span class="line"><span>│   └── → TraeCode</span></span>
<span class="line"><span>│       ├── 要精细控制每一步？ → IDE 模式</span></span>
<span class="line"><span>│       ├── 用自然语言从需求推到预览？ → SOLO 模式</span></span>
<span class="line"><span>│       └── 人已经在 VS Code / JetBrains？ → TraeCode Plugin（地图一行，跟企业页）</span></span>
<span class="line"><span>├── 做 PPT / 文档 / 数据分析 / 跨端派任务</span></span>
<span class="line"><span>│   └── → TraeWork（不在本目录）</span></span>
<span class="line"><span>├── 团队采购、仓库索引上限、SOC 2</span></span>
<span class="line"><span>│   └── → TRAE Enterprise</span></span>
<span class="line"><span>├── 聊天 / 通用助手</span></span>
<span class="line"><span>│   └── → 豆包（#79）</span></span>
<span class="line"><span>├── 搭 Bot / 工作流</span></span>
<span class="line"><span>│   └── → 扣子（#81）</span></span>
<span class="line"><span>└── 在自己的服务里调模型 API</span></span>
<span class="line"><span>    └── → 火山方舟（#82）</span></span></code></pre></div><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 选对表面</td><td><a href="./trae.html#1-选表面中国站-vs-国际站">教程 · 中国站 vs 国际站</a></td><td>不要装错站、登错号</td></tr><tr><td>2. 装上能开项目</td><td><a href="./trae.html">教程 · 安装与第一项目</a></td><td>从官方下载页装上，打开本地文件夹或克隆仓库</td></tr><tr><td>3. 分清两种模式</td><td><a href="./trae.html#5-切换-ide-模式与-solo-模式">教程 · IDE / SOLO</a></td><td>左上角切换，不要把 SOLO 当成 TraeWork</td></tr><tr><td>4. 回查入口</td><td><a href="./trae-cheatsheet.html">速查表</a></td><td>OS、设备上限、官方 URL</td></tr></tbody></table><h2 id="功能速查" tabindex="-1">功能速查 <a class="header-anchor" href="#功能速查" aria-label="Permalink to &quot;功能速查&quot;">​</a></h2><p>只列官方文档已经写明的能力。细节进教程或官方页。</p><table tabindex="0"><thead><tr><th>能力</th><th>一句话</th><th>官方页</th></tr></thead><tbody><tr><td>IDE 模式</td><td>保留编辑器、终端、调试、插件、源代码管理</td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a></td></tr><tr><td>SOLO 模式</td><td>AI 主导：需求 → 生成 → 测试 → 预览；左上角切换</td><td><a href="https://docs.trae.ai/ide/solo-mode" target="_blank" rel="noreferrer">SOLO 模式概览</a></td></tr><tr><td>打开项目</td><td>导入本地文件夹 / 从 GitHub 克隆 / 从 URL 克隆</td><td><a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">快速开始</a></td></tr><tr><td>CUE</td><td>补全、链式补全、多行修改、修改点预测；Py / TS / Go 智能导入与重命名</td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a></td></tr><tr><td>智能体</td><td>自然语言拆任务、检索仓库、调工具；可自定义 + MCP</td><td>同上</td></tr><tr><td>上下文</td><td>文件、文件夹、片段、终端、仓库、文档集、网页</td><td>同上</td></tr><tr><td>隐私模式</td><td>开启后对话 / 代码 / 生成结果不用于分析、优化或训练；代码文件留在本地</td><td>同上</td></tr><tr><td>沙箱</td><td>智能体命令在受限环境执行</td><td>同上</td></tr><tr><td>远程</td><td>Remote SSH、WSL</td><td>同上</td></tr><tr><td>设备上限</td><td>国际站 <strong>3</strong> 台；中国站 <strong>10</strong> 台。Web 版 TraeWork 不计入</td><td><a href="https://docs.trae.ai/ide/device-limit" target="_blank" rel="noreferrer">intl</a> · <a href="https://docs.trae.cn/ide_device-limit.md" target="_blank" rel="noreferrer">CN</a></td></tr></tbody></table><h2 id="套餐-只抄官方-不猜价格" tabindex="-1">套餐（只抄官方，不猜价格） <a class="header-anchor" href="#套餐-只抄官方-不猜价格" aria-label="Permalink to &quot;套餐（只抄官方，不猜价格）&quot;">​</a></h2><ul><li>国际站现行档位在 <a href="https://www.trae.ai/pricing" target="_blank" rel="noreferrer">www.trae.ai/pricing</a>：<strong>Lite / Pro / Pro+ / Ultra</strong>。该页写 Pro <strong>Free for 7 days. Then $10/month.</strong>；AI 请求按 token 折成 Dollar Usage 从月度余额扣。Lite / Pro+ / Ultra 的完整月费以该页为准，本站不补未抓全的数字。</li><li>文档站另有 <a href="https://docs.trae.ai/ide/billing" target="_blank" rel="noreferrer">(Legacy) Plans &amp; billing</a>。官方已标 Legacy，不要把旧免费/Pro 次数表当现行。</li><li>中国站 <a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer">llms.txt</a> 有「以积分为核心的计费模式」条目。金额与折算去中国站文档，这里不写死。</li><li>企业方案：定价页写 Contact us via BytePlus；产品页 <a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">Enterprise</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>打开 <a href="./trae.html">TraeCode 教程</a>，先选中国站或国际站，再从官方下载页安装。</li><li>OS、设备上限、官方 URL 去 <a href="./trae-cheatsheet.html">速查表</a>。</li><li>官方深读从 <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai</a> 或 <a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">docs.trae.cn</a> 进。</li></ol>`,22)])])}const k=a(s,[["render",o]]);export{w as __pageData,k as default};
